// 1. Obtener los ítems de entrada del nodo "Orquestador Turnos"
const items = $('Orquestador Turnos').all();

// Si no hay ítems, retornar array vacío
if (!items || items.length === 0) {
    return [];
}

// 2. Función segura para extraer el valor tras una etiqueta sin usar RegExp
function obtenerValor(texto, etiqueta) {
    if (!texto) return "No especificado";

    // Normalizar texto eliminando asteriscos y saltos escapados
    const textoLimpio = texto.replace(/\\n/g, "\n").replace(/\*\*/g, "");

    const indiceEtiqueta = textoLimpio.toLowerCase().indexOf(etiqueta.toLowerCase() + ":");
    if (indiceEtiqueta === -1) return "No especificado";

    // Cortar desde donde termina la etiqueta + los dos puntos
    const inicioValor = indiceEtiqueta + etiqueta.length + 1;
    const subtexto = textoLimpio.substring(inicioValor);

    // El valor termina en el primer salto de línea que encuentre
    const finLinea = subtexto.indexOf("\n");
    let valor = finLinea !== -1 ? subtexto.substring(0, finLinea) : subtexto;

    return valor.trim() || "No especificado";
}

// 3. Procesar cada ítem recibido y retornar el JSON estructurado
return items.map(item => {
    // Capturar la salida de texto del Orquestador (salida, text o output)
    const textoProduccion = item.json.salida || item.json.text || item.json.output || "";

    return {
        json: {
            Servicio: obtenerValor(textoProduccion, "Servicio"),
            Costo: obtenerValor(textoProduccion, "Costo del servicio"),
            Fecha: obtenerValor(textoProduccion, "Fecha"),
            Hora: obtenerValor(textoProduccion, "Hora"),
            Correo: obtenerValor(textoProduccion, "Correo de contacto"),
            Nombre: obtenerValor(textoProduccion, "Nombre"),
            Apellido: obtenerValor(textoProduccion, "Apellido"),
            Incluye: obtenerValor(textoProduccion, "Incluye"),
            RepuestosIncluidos: obtenerValor(textoProduccion, "Repuestos incluidos"),
            Demora: obtenerValor(textoProduccion, "Demora"),
            ChatID: obtenerValor(textoProduccion, "ID CHAT")
        }
    };
});

parameters.text:
=Sos un condensador de conversaciones comerciales. Analiza el siguiente intercambio y devolve UNICAMENTE un objeto JSON valido, sin texto adicional, sin backticks y sin explicaciones.

Formato exacto:
{"asunto_principal": "tema central en una frase", "puntos_clave": ["hecho accionable 1", "hecho accionable 2"], "accion_requerida": "proximo paso concreto"}

Contexto previo acumulado: {{ $('Orquestador Turnos').item.json.last_summary || 'ninguno' }}
Mensaje del cliente: {{ $('Webhook: Mensaje Chat Cliente').item.json.chatInput }}
Respuesta del asesor: {{ $('Orquestador Turnos').item.json.output }}

Regla critica: guarda SOLO hechos accionables (presupuestos, medidas, plazos, decisiones). Ignora saludos y charla social. Maximo 3 puntos_clave.

