for (const item of $input.all()) {
  // Obtiene el texto buscando en 'Texto', 'text' u 'output'
  let rawText = item.json.Texto || item.json.text || item.json.output || "";

  // Remueve marcas de bloque de código como ```json ... ``` si el LLM las incluyó
  rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

  try {
    const parsedData = JSON.parse(rawText);

    item.json.asunto_principal = parsedData.asunto_principal || "";
    item.json.puntos_clave = Array.isArray(parsedData.puntos_clave) 
      ? parsedData.puntos_clave.join('\n• ') 
      : (parsedData.puntos_clave || "");
    item.json.accion_requerida = parsedData.accion_requerida || "";
  } catch (error) {
    // Si no es un JSON válido, asigna valores por defecto
    item.json.asunto_principal = rawText;
    item.json.puntos_clave = "";
    item.json.accion_requerida = "";
  }
}

return $input.all();

